function parseUnifiedDiff(text) {
	return text.split("\n").map((line) => {
		if (line.startsWith("@@")) return {
			kind: "hunk",
			text: line
		};
		if (line.startsWith("+") && !line.startsWith("+++")) return {
			kind: "add",
			text: line
		};
		if (line.startsWith("-") && !line.startsWith("---")) return {
			kind: "del",
			text: line
		};
		if (line.startsWith("+++") || line.startsWith("---")) return {
			kind: "meta",
			text: line
		};
		return {
			kind: "ctx",
			text: line
		};
	});
}
